#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Sets up Knock (notification vendor) keys in .env.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# ask_until KEY PREFIX "Prompt" [secret] repeats ask/ask_secret until the value
# starts with PREFIX, so a mis-paste is caught here rather than in the app.
ask_until() {
  local key="$1" prefix="$2" prompt="$3" secret="${4:-}"
  while :; do
    if [[ -n "$secret" ]]; then ask_secret "$key" "$prompt"; else ask "$key" "$prompt"; fi
    [[ "${!key}" == "$prefix"* ]] && return 0
    warn "that doesn't start with ${prefix}, so it's probably the wrong value. Try again."
  done
}

# ask_long_secret KEY "Prompt" is ask_secret for values longer than one terminal
# line. In its normal line mode the terminal keeps at most MAX_CANON bytes per
# line: 1024 on macOS, where a longer paste loses its Enter and read hangs, and
# 4096 on Linux, where it's silently cut short. Line mode is switched off just
# for this read, so a paste of any length gets through (Backspace doesn't work
# while it's off). An EXIT/INT trap restores the terminal if you press Ctrl-C.
_STTY_SAVED=""
_restore_tty() { [[ -n "$_STTY_SAVED" ]] && stty "$_STTY_SAVED" 2>/dev/null; _STTY_SAVED=""; }
trap _restore_tty EXIT
trap '_restore_tty; exit 130' INT
ask_long_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  # stty hides the input instead of read -s: read -s restores its own snapshot of
  # the terminal after a Ctrl-C trap runs, which would leave line mode off.
  if [[ -t 0 ]]; then _STTY_SAVED=$(stty -g); stty -icanon -echo min 1 time 0; fi
  IFS= read -r input || rc=1
  _restore_tty
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  input="${input//[[:space:]]/}"   # a stray space or CR from the paste
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

run_wizard() {

TOTAL_STAGES=6

# .env lives at the repo root, wherever the wizard is run from.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

banner "Knock setup for Cadence Notifications"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Create a Knock account"
say "Knock is the hosted vendor behind Cadence's Notifications and the Notification Feed."
say "Its free Developer plan (10K messages a month) is all we need."
open_url "https://dashboard.knock.app/signup"
step "Sign up (or log in if you already have an account) and finish onboarding."
step "Stay on the single environment new accounts start with."
warn "Don't click 'Enable environments': you can't undo it, and we don't need it yet."
note "(Accounts made before Oct 2026 already have Development + Production."
note " If yours does, use the Development environment in every stage below.)"
pause "Press Enter once you're in the Knock dashboard."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "API keys"
say "The server triggers Notifications with the secret key. The browser reads"
say "the Notification Feed with the public key."
open_url "https://dashboard.knock.app"
step "In the left sidebar, open Platform → API keys."
step "Copy the Public key (starts with pk_)."
ask_until KNOCK_PUBLIC_API_KEY "pk_" "Paste the public key:"
write_env KNOCK_PUBLIC_API_KEY "$KNOCK_PUBLIC_API_KEY"
step "Now copy the Secret key (starts with sk_)."
ask_until KNOCK_API_KEY "sk_" "Paste the secret key (hidden):" secret
write_env KNOCK_API_KEY "$KNOCK_API_KEY"
note "KNOCK_API_KEY is the name the Knock Node SDK reads by default."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Signing key for user tokens"
say "Our server uses this private key to sign an RS256 user token for whichever user"
say "the DevUI switcher picks. The Notification Feed authenticates with that token."
step "Stay on Platform → API keys and find the signing keys section."
step "Click to generate a signing key."
warn "Knock shows the private key only once. Copy it before you close the dialog."
step "Copy the base-64 encoded version: one line starting with LS0tLS1CRUdJTi."
note "(Not the multi-line PEM under 'Advanced': .env needs the one-line form.)"
while :; do
  ask_long_secret KNOCK_SIGNING_KEY "Paste the base-64 signing key (hidden, then press Enter):" || exit 1
  [[ "$KNOCK_SIGNING_KEY" == LS0tLS1CRUdJTi* ]] && break
  warn "that doesn't start with LS0tLS1CRUdJTi, so it's probably the wrong value. Try again."
done
write_env KNOCK_SIGNING_KEY "$KNOCK_SIGNING_KEY"
note "KNOCK_SIGNING_KEY is the name the Knock Node SDK reads by default."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Turn on enhanced security mode"
say "With it off, anyone holding the public key can read any user's feed. With it on,"
say "Knock rejects feed requests that don't carry a user token our server signed."
say "We turn it on now so the Knock prototype tests the production-grade path."
step "Stay on Platform → API keys and turn on enhanced security mode."
note "Nothing in Cadence calls Knock yet, so this breaks nothing."
until confirm "Is enhanced security mode turned on?"; do
  warn "Turn it on before moving on. The Knock prototype depends on it."
done

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "In-app feed channel"
say "Notifications reach the Notification Feed through Knock's in-app feed channel."
say "Our server needs its channel ID to read the feed."
open_url "https://dashboard.knock.app/~/settings/integrations/channels"
step "On Channels and sources, look for an in-app feed channel."
step "If there isn't one, create one with the in-app feed type, provider Knock,"
step "and name it 'In-app feed'."
step "Open the channel and copy its channel ID (a UUID)."
ask KNOCK_FEED_CHANNEL_ID "Paste the channel ID:"
until [[ "$KNOCK_FEED_CHANNEL_ID" =~ ^[0-9a-fA-F-]{36}$ ]]; do
  warn "That doesn't look like a UUID (8-4-4-4-12 hex). Try again."
  ask KNOCK_FEED_CHANNEL_ID "Paste the channel ID:"
done
write_env KNOCK_FEED_CHANNEL_ID "$KNOCK_FEED_CHANNEL_ID"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Check the secret key"
say "Asking Knock for a user that doesn't exist: 404 means the key works, 401 means it doesn't."
code=$(curl -s -o /dev/null -w '%{http_code}' \
  -H "Authorization: Bearer $KNOCK_API_KEY" \
  "https://api.knock.app/v1/users/setup-knock-wizard-check" || echo "000")
case "$code" in
  404|200) printf '  %s✓ Knock accepted the secret key%s (HTTP %s)\n' "$GREEN" "$RESET" "$code" ;;
  401)     warn "Knock rejected the secret key (HTTP 401). Re-run and paste it again."
           SKIPPED+=("KNOCK_API_KEY was rejected by Knock (HTTP 401)") ;;
  403)     warn "HTTP 403: either Knock rejected the key or a proxy/firewall blocked api.knock.app."
           SKIPPED+=("check KNOCK_API_KEY by hand (got HTTP 403)") ;;
  *)       warn "Couldn't reach api.knock.app (HTTP $code), so the key wasn't checked."
           SKIPPED+=("check KNOCK_API_KEY by hand: api.knock.app was unreachable") ;;
esac
pause

finish
note "Next: the Knock prototype uses these values."
printf '\n'
}

run_wizard "$@"; exit
